INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("東山奈央", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", 0, "ヒヨリ", 44, 2, "人助けが大好き！　前向き格闘娘", "獣人族", 100101, 27, "トゥインクルウィッシュ", "A", "人助け、応援", 16, 155, 8);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("種田梨沙", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", 0, "ユイ", 47, 2, "戦闘のサポートが得意な、心優しい少女", "ヒューマン", 100201, 5, "トゥインクルウィッシュ", "O", "料理、人間観察", 17, 158, 4);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("早見沙織", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", 0, "レイ", 46, 2, "クールで何事にも真っ直ぐな剣士", "魔族", 100301, 12, "トゥインクルウィッシュ", "B", "読書、乗馬、お茶", 18, 163, 1);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("諸星すみれ", "イタズラなら任せて！\nにいちゃん、引っかからないように気を付けなよー♪", 0, "ミソギ", 27, 5, "探検好きのイタズラっ子", "ヒューマン", 100401, 10, "リトルリリカル", "O", "いたずら、探検", 9, 128, 8);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("下田麻美", "？？？", 0, "マツリ", 40, 8, "ヒーローに憧れる騎士見習いの少女", "獣人族", 100501, 25, "王宮騎士団（NIGHTMARE）", "O", "ヒーローごっこ", 12, 146, 11);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("浅倉杏美", "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！", 0, "アカリ", 42, 7, "甘え上手なみんなの人気者", "魔族", 100601, 22, "悪魔偽王国軍（ディアボロス）", "O", "サックス", 13, 150, 11);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("雨宮天", "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", 0, "ミヤコ", 32, 7, "プリン大好きゴースト娘", "魔族", 100701, 23, "悪魔偽王国軍（ディアボロス）", "B", "プリンを食べること", 14, 130, 1);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("大空直美", "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", 0, "ユキ", 40, 15, "ボクは誰よりも美しい", "エルフ", 100801, 10, "ヴァイスフリューゲル　ランドソル支部", "AB", "鏡で自分を見ること", 14, 150, 10);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("髙野麻美", "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", 0, "アンナ", 45, 13, "前世を信じる中二病患者、「疾風の冥姫」", "魔族", 100901, 5, "トワイライトキャラバン", "A", "小説執筆", 17, 159, 7);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("内田真礼", "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", 0, "マホ", 42, 10, "マホマホ王国のプリンセス", "獣人族", 101001, 22, "自警団（カォン）", "O", "空想、ぬいぐるみ集め", 16, 155, 9);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("阿澄佳奈", "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", 0, "リノ", 44, 3, "人懐っこくてマシンガントークな妹系少女", "ヒューマン", 101101, 25, "ラビリンス", "A", "お裁縫", 15, 156, 8);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("大橋彩香", "私はハツネ！　困っている人の味方だよ！\n困った時は、いつでも言ってね♪\n私のちょ…ま、魔法で助けてあげるから！", 0, "ハツネ", 46, 6, "みんなのために超能力を使う眠り姫", "エルフ", 101201, 24, "フォレスティエ", "A", "妹と遊ぶこと、二度寝、昼寝、早寝", 17, 156, 12);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("佳村はるか", "", 0, "ナナカ", 55, 13, "オタク全開な魔法少女", "魔族", 101301, 21, "トワイライトキャラバン", "O", "読書、魔法", 18, 166, 8);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("水瀬いのり", "test", 0, "カスミ", 41, 10, "頭脳明晰な美少女名探偵", "獣人族", 101401, 3, "自警団（カォン）", "AB", "読書、推理", 15, 152, 11);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("國府田マリ子", "test", 0, "ミサト", 54, 6, "母性溢れる優しいみんなの「ミサト先生」", "エルフ", 101501, 5, "フォレスティエ", "O", "絵本作り", 21, 165, 9);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("上坂すみれ", "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", 0, "スズナ", 48, 14, "天真爛漫で人気者のカリスマモデル", "魔族", 101601, 10, "ルーセント学院", "O", "ファッション", 17, 167, 4);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("高森奈津美", "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", 0, "カオリ", 53, 10, "いつでも「なんくるないさ～」な天然娘", "獣人族", 101701, 7, "自警団（カォン）", "A", "踊り、空手", 17, 158, 7);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("伊藤静", "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～", 0, "イオ", 52, 14, "多くの男性を魅了する無垢な女教師", "魔族", 101801, 14, "ルーセント学院", "B", "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", 23, 162, 8);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("日高里菜", "ぴょんぴょん、うさぎさんになりたいな～♪　\nミミ、うさぎさんになれたら、\n最初におにいちゃんに見せてあげるね！", 0, "ミミ", 21, 5, "お歌もにんじんも、ウサギさんも大好き♪", "獣人族", 102001, 3, "リトルリリカル", "O", "かわいいもの集め", 10, 117, 4);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("植田佳奈", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", 0, "クルミ", 40, 9, "泣き虫で臆病な守ってあげたい女の子", "ヒューマン", 102101, 9, "サレンディア救護院", "B", "観劇、おままごと", 12, 150, 6);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("原紗友里", "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…", 0, "ヨリ", 40, 7, "人見知りであまのじゃくな女の子", "魔族", 102201, 22, "悪魔偽王国軍（ディアボロス）", "O", "ゲーム全般", 13, 150, 11);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("芹澤優", "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", 0, "アヤネ", 38, 9, "ぷうきちといつも一緒！", "ヒューマン", 102301, 10, "サレンディア救護院", "B", "屋内でできる遊び", 14, 148, 5);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("悠木碧", "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", 0, "スズメ", 43, 9, "お嬢さまのためにがんばるドジっ娘メイド", "ヒューマン", 102501, 12, "サレンディア救護院", "O", "ご奉仕", 15, 154, 12);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("小岩井ことり", "test", 0, "リン", 42, 11, "遊びと睡眠が何より大事なぐうたら娘", "獣人族", 102601, 1, "牧場（エリザベスパーク）", "B", "あんパン", 17, 144, 1);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("橋本ちなみ", "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", 0, "エリコ", 43, 13, "運命の相手に一途すぎる乙女", "魔族", 102701, 30, "トワイライトキャラバン", "B", "実験、裁縫、料理", 16, 154, 7);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("堀江由衣", "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", 0, "サレン", 43, 9, "救護院を経営する優しい庶民派お嬢様", "エルフ", 102801, 4, "サレンディア救護院", "A", "経営、お茶会", 17, 156, 10);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("日笠陽子", "いつか世界中の人達をファンにしてみせる！\nトップアイドルになるその日まで、\n応援よろしくね♪", 0, "ノゾミ", 40, 4, "歌って踊れる大人気アイドル", "ヒューマン", 102901, 24, "カルミナ", "B", "舞台鑑賞、ダンス", 17, 157, 1);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("佐藤聡美", "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", 0, "ニノン", 51, 15, "トーゴクの神秘、オシエテクダサイ！", "ヒューマン", 103001, 31, "ヴァイスフリューゲル　ランドソル支部", "O", "忍法開発", 16, 163, 8);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("大坪由佳", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", 0, "シノブ", 42, 7, "占いが得意な霊能少女", "魔族", 103101, 22, "悪魔偽王国軍（ディアボロス）", "AB", "占い", 18, 157, 12);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("松嵜麗", "この私とともにいる限り、\nお金に不自由はさせませんわ！", 0, "アキノ", 45, 12, "一人前の商人を目指すパワフルお嬢様", "ヒューマン", 103201, 12, "メルクリウス財団", "AB", "慈善事業", 18, 157, 3);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("新田恵海", "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！", 0, "マヒル", 35, 11, "みんなを笑顔にするお笑い牧場主", "ヒューマン", 103301, 3, "牧場（エリザベスパーク）", "B", "漫才", 20, 142, 3);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("今井麻美", "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", 0, "ユカリ", 55, 12, "純情でほっとけない大人の女性", "エルフ", 103401, 16, "メルクリウス財団", "A", "ウインドーショッピング", 22, 164, 3);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("小倉唯", "test", 0, "キョウカ", 21, 5, "礼儀正しくしっかり者のちびっ子優等生", "エルフ", 103601, 2, "リトルリリカル", "A", "お勉強", 8, 118, 2);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("茅原実里", "test", 0, "トモ", 43, 8, "義理堅くてからかい好きな剣術少女", "ヒューマン", 103701, 11, "王宮騎士団（NIGHTMARE）", "A", "剣術、年長者をからかう", 13, 149, 8);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("小清水亜美", "ゴホッ、ゴホッ…か、身体は弱いけど、\nせめて気持ちだけでも前向きに…！\nあっ、でもダメ…立ちくらみが…", 0, "シオリ", 40, 11, "読書が趣味の病弱少女", "獣人族", 103801, 3, "牧場（エリザベスパーク）", "A", "読書、お散歩", 14, 153, 11);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("花澤香菜", "友達ができるその日まで…\nBB団で\nトレーニングですっ！", 0, "アオイ", 44, 6, "「友達」に憧れる、エルフの森の女の子", "エルフ", 104001, 6, "フォレスティエ", "AB", "友達作りのイメトレ", 13, 158, 6);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("福原綾香", "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", 0, "チカ", 46, 4, "人々を守るために歌う、唱喚士の少女", "ヒューマン", 104201, 3, "カルミナ", "O", "各種楽器", 17, 163, 6);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("小松未可子", "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！", 0, "マコト", 54, 10, "男勝りで情に厚いワイルド娘", "獣人族", 104301, 9, "自警団（カォン）", "O", "お菓子作り", 17, 168, 8);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("丹下桜", "test", 0, "イリヤ", 50, 7, "かつては夜を支配した最強の吸血鬼", "魔族", 104401, 5, "悪魔偽王国軍（ディアボロス）", "A", "世界征服", "??", 172, 5);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("長妻樹里", "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", 0, "クウカ", 49, 15, "妄想大好き！　ほんとは照れ屋な女の子", "ヒューマン", 104501, 19, "ヴァイスフリューゲル　ランドソル支部", "AB", "小説を読むこと", 18, 157, 11);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("沼倉愛美", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", 0, "タマキ", 48, 12, "弱きを助け強きをくじく猫娘", "獣人族", 104601, 1, "メルクリウス財団", "AB", "猫とたわむれること", 19, 158, 3);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("川澄綾子", "？？？", 0, "ジュン", 50, 8, "素顔を見せない冷静沈着な女性騎士", "ヒューマン", 104701, 25, "王宮騎士団（NIGHTMARE）", "A", "格闘技、湯浴み", 25, 171, 10);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("田所あずさ", "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", 0, "ミフユ", 49, 12, "仕事も私事も効率優先な傭兵少女", "ヒューマン", 104801, 11, "メルクリウス財団", "O", "傭兵などのアルバイト", 20, 163, 11);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("生天目仁美", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", 0, "シズル", 54, 3, "お姉ちゃんがお世話してあげるからねっ！", "ヒューマン", 104901, 24, "ラビリンス", "O", "家事全般", 18, 168, 10);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("久野美咲", "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", 0, "ミサキ", 22, 14, "ちょっとおませな恋に恋する女の子", "魔族", 105001, 3, "ルーセント学院", "A", "ファッション誌鑑賞、コスメ集め", 11, 120, 1);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("三石琴乃", "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", 0, "ミツキ", 53, 13, "実験が趣味の危険な科学者", "ヒューマン", 105101, 7, "トワイライトキャラバン", "A", "研究、実験", 27, 166, 3);
