INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("沼倉愛美", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", 0, "タマキ（サマー）", 48, 12, "弱きを助け強きをくじく猫娘", "獣人族", 107901, 1, "メルクリウス財団", "AB", "猫とたわむれること", 19, 158, 3);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("田所あずさ", "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", 0, "ミフユ（サマー）", 49, 12, "仕事も私事も効率優先な傭兵少女", "ヒューマン", 108001, 11, "メルクリウス財団", "O", "傭兵などのアルバイト", 20, 163, 11);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("大坪由佳", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", 0, "シノブ（ハロウィン）", 42, 7, "占いが得意な霊能少女", "魔族", 108101, 22, "悪魔偽王国軍（ディアボロス）", "AB", "占い", 18, 157, 12);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("雨宮天", "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", 0, "ミヤコ（ハロウィン）", 32, 7, "プリン大好きゴースト娘", "魔族", 108201, 23, "悪魔偽王国軍（ディアボロス）", "B", "プリンを食べること", 14, 130, 1);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("久野美咲", "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", 0, "ミサキ（ハロウィン）", 22, 14, "ちょっとおませな恋に恋する女の子", "魔族", 108301, 3, "ルーセント学院", "A", "ファッション誌鑑賞、コスメ集め", 11, 120, 1);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("福原綾香", "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", 0, "チカ（クリスマス）", 46, 4, "人々を守るために歌う、唱喚士の少女", "ヒューマン", 108401, 3, "カルミナ", "O", "各種楽器", 17, 163, 6);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("植田佳奈", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", 0, "クルミ（クリスマス）", 40, 9, "泣き虫で臆病な守ってあげたい女の子", "ヒューマン", 108501, 9, "サレンディア救護院", "B", "観劇、おままごと", 12, 150, 6);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("芹澤優", "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", 0, "アヤネ（クリスマス）", 38, 9, "ぷうきちといつも一緒！", "ヒューマン", 108601, 10, "サレンディア救護院", "B", "屋内でできる遊び", 14, 148, 5);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("東山奈央", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", 0, "ヒヨリ（ニューイヤー）", 44, 2, "人助けが大好き！　前向き格闘娘", "獣人族", 108701, 27, "トゥインクルウィッシュ", "A", "人助け、応援", 16, 155, 8);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("種田梨沙", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", 0, "ユイ（ニューイヤー）", 47, 2, "戦闘のサポートが得意な、心優しい少女", "ヒューマン", 108801, 5, "トゥインクルウィッシュ", "O", "料理、人間観察", 17, 158, 4);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("早見沙織", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", 0, "レイ（ニューイヤー）", 46, 2, "クールで何事にも真っ直ぐな剣士", "魔族", 108901, 12, "トゥインクルウィッシュ", "B", "読書、乗馬、お茶", 18, 163, 1);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("橋本ちなみ", "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", 0, "エリコ（バレンタイン）", 43, 13, "運命の相手に一途すぎる乙女", "魔族", 109001, 30, "トワイライトキャラバン", "B", "実験、裁縫、料理", 16, 154, 7);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("生天目仁美", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", 0, "シズル（バレンタイン）", 54, 3, "お姉ちゃんがお世話してあげるからねっ！", "ヒューマン", 109101, 24, "ラビリンス", "O", "家事全般", 18, 168, 10);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("日笠陽子", "私はアン！一応、マナリア王国の\n第一王女だけど…あまりかしこまらないで、\n気軽に仲良くしてくれたら嬉しいな！", 0, "アン", 55, "", "英霊と契約を結んだマナリアの天才王女", "ヒューマン", 109201, 1, "？？？", "AB", "読書", 17, 156, 12);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("こやまきみこ", "ルゥはルゥですぅ！マナリア魔法学院に\n通ってるですぅ。あなたもルゥの\nお友だちになってくれるですか？", 0, "ルゥ", 45, "", "マナリア魔法学院の新入生", "ヒューマン", 109301, 4, "？？？", "O", "食べること、眠ること", 16, 144, 2);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("福原綾香", "私はグレア。竜と人、両方の血を\n受け継いでいるの…\nえっと…よ、よろしくね", 0, "グレア", 67, "", "人を超越した力を有す心優しい竜姫", "半人半竜", 109401, 3, "？？？", "B", "ピアノ", 17, 167, 11);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("長妻樹里", "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", 0, "クウカ（オーエド）", 49, 15, "妄想大好き！　ほんとは照れ屋な女の子", "ヒューマン", 109501, 19, "ヴァイスフリューゲル　ランドソル支部", "AB", "小説を読むこと", 18, 157, 11);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("佐藤聡美", "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", 0, "ニノン（オーエド）", 51, 15, "トーゴクの神秘、オシエテクダサイ！", "ヒューマン", 109601, 31, "ヴァイスフリューゲル　ランドソル支部", "O", "忍法開発", 16, 163, 8);
