INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("福原綾香", "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", 0, "チカ（サマー）", 46, 4, "人々を守るために歌う、唱喚士の少女", "ヒューマン", 117301, 3, "カルミナ", "O", "各種楽器", 17, 163, 6);
