INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("大空直美", "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", 0, "ユキ（オーエド）", 40, 15, "ボクは誰よりも美しい", "エルフ", 117601, 10, "ヴァイスフリューゲル　ランドソル支部", "AB", "鏡で自分を見ること", 14, 150, 10);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("高森奈津美", "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", 0, "カオリ（ハロウィン）", 53, 10, "いつでも「なんくるないさ～」な天然娘", "獣人族", 117701, 7, "自警団（カォン）", "A", "踊り、空手", 17, 158, 7);
