INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("上坂すみれ", "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", 0, "スズナ（ハロウィン）", 48, 14, "天真爛漫で人気者のカリスマモデル", "魔族", 117901, 10, "ルーセント学院", "O", "ファッション", 17, 167, 4);
